      "Hazardous Material Handling (HAZMAT)",
      "Lockout/Tagout (LOTO)",
      "NEBOSH",
      "IOSH",
      "OSHA Compliance",
      "ISO 45001",
      "ISO 14001",
      "Environmental Health and Safety (EHS)",
      "Risk Mitigation",
      "Behavior-Based Safety (BBS)",
      "Safety Culture Promotion",
      "First Aid & CPR",
      "Industrial Hygiene",
      "Ergonomics Assessment",
      // Healthcare & Clinical
      "Patient Care",
      "Triage",
      "Vital Signs",
      "HIPAA",
      "Medication Administration",
      "EHR",
      "EMR",
      "Epic",
      "Cerner",
      "CPR",
      "BLS",
      "ACLS",
      "Patient Assessment",
      "Phlebotomy",
      "Wound Care",
      "Patient Education",
      "Infection Control",
      "IV Therapy",
      "Care Planning",
      "Clinical Documentation",
      "Telehealth",
      "Discharge Planning",
      // Finance & Accounting
      "GAAP",
      "Financial Reporting",
