      const nextVersionNumber = parseInt(existingVersions.rows[0]?.count || "0", 10) + 1;
      const modeSuffix = optimizationMode === "aggressive_keywords" ? " (Max ATS Match)" : optimizationMode === "executive" ? " (Executive Focus)" : optimizationMode === "fresher" ? " (Foundational)" : "";
      const versionName = `${job.detectedRole} \u2013 v${nextVersionNumber}${modeSuffix}`;
      const versionId = v4_default();
